// `@types/node`'s `node:` alias shape: an ambient block that declares nothing
// of its own and only stars another ambient module back out.
//
//     declare module "node:child_process" { export * from "child_process"; }
//
// A star re-export IS an export, so a named import from the alias reaches the
// starred module's declarations. Emptying such a table left every name `any`,
// and with it the contextual signature of every callback written for one.
declare module "cproc" {
  class CP {
    on(event: string, listener: (...args: any[]) => void): this;
    on(event: "exit", listener: (code: number) => void): this;
    pid: number;
  }
  interface Options {
    shell: boolean;
  }
  export { CP, Options };
}

declare module "node:cproc" {
  export * from "cproc";
}

// A CHAIN of block-less aliases still settles.
declare module "node:cproc2" {
  export * from "node:cproc";
}
